(() => {
    "use strict";
    if (!$loon || !$response || typeof $response.body !== "string") return $done({});
    const WASM_BASE64 = "";
    let wasmInstancePromise;
    let callQueue = Promise.resolve();
    function utf8ToBytes(value) {
        const encoded = unescape(encodeURIComponent(value));
        const bytes = new Uint8Array(encoded.length);
        for (let i = 0; i < encoded.length; i++) bytes[i] = encoded.charCodeAt(i);
        return bytes;
    }
    function bytesToUtf8(bytes) {
        let binary = "";
        for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
        return decodeURIComponent(escape(binary));
    }
    function base64ToBytes(value) {
        const binary = atob(value);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        return bytes;
    }
    function getWasmInstance() {
        if (!wasmInstancePromise) wasmInstancePromise = WebAssembly.instantiate(base64ToBytes(WASM_BASE64)).then(result => result.instance);
        return wasmInstancePromise;
    }
    function processBody(instance, body) {
        const input = utf8ToBytes(body);
        const exports = instance.exports;
        if (!exports.memory || !exports.alloc || !exports.process || !exports.output_len || !exports.dealloc) throw new Error("WASM ABI 不完整");
        const inputPointer = exports.alloc(input.length);
        if (!inputPointer) throw new Error("WASM 输入分配失败");
        try {
            new Uint8Array(exports.memory.buffer, inputPointer, input.length).set(input);
            const outputPointer = exports.process(inputPointer, input.length);
            const outputLength = exports.output_len();
            if (!outputPointer && outputLength) throw new Error("WASM 输出无效");
            return bytesToUtf8(new Uint8Array(exports.memory.buffer, outputPointer, outputLength));
        } finally {
            exports.dealloc(inputPointer, input.length);
        }
    }
    function run() {
        return getWasmInstance().then(instance => {
            const previous = callQueue;
            let release;
            callQueue = new Promise(resolve => { release = resolve; });
            return previous.then(() => {
                try { return processBody(instance, $response.body); }
                finally { release(); }
            });
        });
    }
    run().then(body => body === $response.body ? $done({}) : $done({ body })).catch(error => {
        console.log(`[DJDuoduo] WASM 跳过: ${error.message || error}`);
        $done({});
    });
})();
